//go:build ignore
package main

import (
	"bytes"
	"encoding/gob"
	"fmt"
	"os"
)

type IdsMap map[int]string

func main() {
	gob.RegisterName("IdsMap", IdsMap{})
	m := IdsMap{2: "7a7dea1e-9771-4439-a76c-9e9bc1801632", 3: "23ae6c46-b22b-4d11-874a-b607785d97fa", 4: "1d7b1958-419a-442f-aece-b7e3fb667188"}
	var buf bytes.Buffer
	if err := gob.NewEncoder(&buf).Encode(m); err != nil { panic(err) }
	os.WriteFile("/tmp/gobdec/std.gob", buf.Bytes(), 0644)
	fmt.Println("wrote", buf.Len())
}
EOF
go run enc.go && od -A d -t x1z /tmp/gobdec/std.gob

