//go:build ignore
package main
import ("bytes";"encoding/gob";"fmt";"os";"time")
type Query struct {
	Cmd           string
	IDs           []int
	Tags          []string
	AntiTags      []string
	Project       string
	AntiProjects  []string
	Due           time.Time
	DateFilter    string
	Priority      string
	Template      bool
	Text          string
	IgnoreContext bool
	Note          string
}
type State struct { Context Query }
func main(){
	b,_:=os.ReadFile(os.Args[1])
	var m map[string]int
	if err:=gob.NewDecoder(bytes.NewReader(b)).Decode(&m); err==nil { fmt.Printf("uuid->id map: %v\n",m); return }
	var s State
	if err:=gob.NewDecoder(bytes.NewReader(b)).Decode(&s); err==nil { fmt.Printf("state: %+v\n",s.Context); return }
	fmt.Println("both failed")
}
EOF
